import * as M from './media-backup.js';
import {prepareImport} from './backup.js';
import * as PUI from './planner-ui.js';
import * as C from './core.js';import * as S from './storage.js';import * as G from './cloud.js';import * as X from './extensions.js';import * as U from './extension-ui.js';
const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),attr=esc, n=v=>Number(v)||0, fmt=(v,d=1)=>Number(v).toFixed(d).replace(/\.0+$/,''), clock=s=>s?new Date(s).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'}):'—',elapsed=s=>{s=Math.max(0,Math.floor(s||0));return [Math.floor(s/3600),Math.floor(s/60)%60,s%60].map(x=>String(x).padStart(2,'0')).join(':')}, niceDate=d=>new Date(d+'T12:00:00').toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'}), labels={lift:'Lifting',run:'Running',swim:'Swimming',walk:'Walking'}, units={lb:'lb',lb_each:'lb / dumbbell',bodyweight:'bodyweight',sec:'seconds',band:'band / steps',reach:'reaches',step:'step-down'}, navs=[['workout','▦','Workout'],['schedule','▤','Schedule'],['history','◷','History'],['progress','↗','Progress'],['ai','✧','AI'],['settings','⚙','Settings']];
let mediaBackups=[],mediaBusy=false,mediaMessage='';
let db,view='dashboard',date=C.dayKey(),historyFilter='all',progressName='',edit=null,planDraft=null,planMode='recurring',effective=C.dayKey(),until=C.dayKey(),scheduleDay=C.weekday(date),saving=0,failed='',syncing=false,syncMessage='',syncErrors=[],toastTimer,wakeLock,audio,tabLock,proposalInput='',profileDraft=null,planBase=null,editBase=null,planReason='',supersedeFuture=false,clearOverrides=false;
const heads=()=>C.replay(db.events).heads, head=k=>heads().get(k), schedule=()=>head('schedule')?.payload, sessions=()=>[...heads().values()].filter(e=>e.entity==='session').map(e=>e.payload).sort((a,b)=>b.completedAt.localeCompare(a.completedAt)), active=()=>edit||db.draft, plan=d=>C.planFor(schedule(),d), decision=id=>head('decision:'+id)?.payload;
function btn(label,action,extra='',cls='button'){return `<button type="button" class="${cls}" data-act="${action}" ${extra}>${esc(label)}</button>`}const field=(label,html)=>`<label class="label">${esc(label)}</label>${html}`, inp=(value,attrs='',type='text',cls='field')=>`<input class="${cls}" type="${type}" value="${attr(value)}" ${attrs}>`, options=(values,value)=>values.map(([k,l])=>`<option value="${attr(k)}" ${String(k)===String(value)?'selected':''}>${esc(l)}</option>`).join(''), sel=(values,value,attrs='')=>`<select class="field" ${attrs}>${options(values,value)}</select>`, ta=(value,attrs='')=>`<textarea class="field" rows="3" ${attrs}>${esc(value)}</textarea>`, check=(v,attrs='')=>`<input type="checkbox" ${v?'checked':''} ${attrs}>`, note=(s)=>s?`<div class="note space">${esc(s)}</div>`:'', empty=s=>`<div class="empty space">${esc(s)}</div>`, card=(s)=>`<section class="card">${s}</section>`, title=(s,sub='')=>`<h1>${esc(s)}</h1>${sub?`<p class="lead">${esc(sub)}</p>`:''}`;
function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),3000)}
function error(s){failed=s;$('error').innerHTML=s?`<div class="note warning">${esc(s)}</div>`:'';status()}
function status(){if(!db)return;let pending=db.events.filter(e=>!db.remoteIds.includes(e.id)).length+X.initExt(db).events.filter(e=>!X.initExt(db).remoteIds.includes(e.id)).length;$('status').textContent=failed?'Storage error':saving?'Saving…':syncing?'Synchronizing…':syncMessage.startsWith('Sync not verified')?'Sync needs attention':db.config.sheetId?(!G.authorized()?`Reconnect Google${pending?' · '+pending+' pending':''}`:pending?`${pending} local changes`:'Local saved · connected'):'Saved locally';}
function persist(){saving++;status();return S.save(db).then(()=>{saving--;error('');status();return true}).catch(e=>{saving--;error('Local save failed: '+e.message+'. Export a backup immediately.');return false})}
function addEvent(entity,key,payload,source='manual',id){let e=C.eventFor(db.events,entity,key,payload,source,id);C.encodeEvent(e);db.events.push(e);return e}
async function commit(){let ok=await persist();if(ok)scheduleSync();return ok}
function render(){if(!db)return;document.body.dataset.theme=db.prefs.theme||'teal';$('nav').innerHTML=(['dashboard','measurements','measurement-settings','food','planner','subscriptions'].includes(view)?[['dashboard','⌂','Dashboard'],['workout','▦','LiftLog'],['measurements','↗','Measures'],['food','◉','Food'],['settings','⚙','Settings']]:navs).map(([k,i,l])=>`<button class="nav ${view===k?'active':''}" data-act="nav" data-v="${k}"><span class="ico">${i}</span>${l}${k==='ai'&&pendingAI()?`<sup class="ai-count">${pendingAI()}</sup>`:''}</button>`).join('');$('view').innerHTML=({workout:workoutView,schedule:scheduleView,history:historyView,progress:progressView,ai:aiView,settings:settingsView,dashboard:U.dashboard,measurements:U.measurements,'measurement-settings':U.measurementSettings,food:U.food,planner:PUI.planner,subscriptions:PUI.subscriptions}[view])();status();tick()}
function quickAction(id){if(['new-note','new-subscription','calendar'].includes(id)){PUI.quickStart(id);return}if(id==='start-workout'){date=C.dayKey();if(active()){navigate('workout');return}let pending=plan(date).activities.filter(a=>a.kind==='lift'&&!a.optional&&!C.completedFor(db.events,date,a.slot));if(pending.length===1){freshDraft(pending[0]);return}navigate('workout');return}if(['measurements','history','ai'].includes(id)){navigate(id);return}throw Error('Unknown dashboard shortcut')}
function navigate(v){if(v!=='workout'&&edit){if(!confirm('Discard unsaved corrections?'))return;edit=null}view=v;if(v==='settings'&&navigator.onLine&&db.config.clientId)G.prepare().catch(()=>{});render();scrollTo(0,0)}
function setText(e,x){let side=x.side?`${x.side} · `:'';let val=e.unit==='sec'?`${x.reps||'—'} sec`:e.unit==='reach'?`${x.reps||'—'} reaches${x.direction?' / '+x.direction:''}`:e.unit==='band'?`${x.reps||'—'} steps · ${x.band||'band not specified'}`:e.unit==='step'?`${x.reps||'—'} reps · ${x.height||'—'} in${x.weight?` · ${x.weight} lb`:''}`:e.unit==='bodyweight'?`${x.reps||'—'} reps${x.weight?` · ${x.weight} lb added`:''}`:`${x.weight===''?'—':x.weight} ${units[e.unit]} × ${x.reps||'—'}`;return side+val}
function lastExercise(name,before){for(let s of sessions()){if(s.id===before)continue;let e=s.exercises.find(x=>x.name.toLowerCase()===name.toLowerCase()&&x.sets.some(y=>y.done));if(e)return {s,e}}return null}
function pendingAI(){return db.inbox.filter(p=>p.approval!=='REJECTED'&&!decision(p.id)).length}
function pendingRec(name){return db.inbox.filter(p=>!isTechnicalTest(p)&&p.kind==='weight'&&p.approval!=='REJECTED'&&!decision(p.id)&&p.payload.exercise.toLowerCase()===name.toLowerCase()).sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]}
function isTechnicalTest(p){return /\b(test|technical verification|do not use)\b/i.test(p.explanation||'')}
function chosenRec(name){return db.inbox.filter(x=>!isTechnicalTest(x)&&x.kind==='weight'&&x.payload.exercise.toLowerCase()===name.toLowerCase()&&decision(x.id)?.status==='accepted').sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0]}
function workoutView(){let s=active();if(s)return activeView(s);let p=plan(date),weekStart=C.addDays(date,-C.weekday(date));let strip=C.DAY.map((d,i)=>{let dt=C.addDays(weekStart,i),a=plan(dt).activities,done=a.some(x=>C.completedFor(db.events,dt,x.slot))&&a.every(x=>C.completedFor(db.events,dt,x.slot)||x.optional);return `<button class="day ${dt===date?'active':''} ${dt===C.dayKey()?'today':''}" data-act="pickdate" data-date="${dt}">${d.slice(0,3)}<span class="number">${dt.slice(-2)}${done?' ✓':''}</span></button>`}).join('');let next=null;for(let i=0;i<60&&!next;i++){let d=C.addDays(C.dayKey(),i);let a=plan(d).activities.find(x=>!x.optional&&!C.completedFor(db.events,d,x.slot));if(a)next={d,a}}return `<section class="hero"><div class="eyebrow">${date===C.dayKey()?'Today':'Selected date'}</div><h1>${esc(niceDate(date))}</h1><p class="lead">${esc(p.notes||(!p.activities.length?'No scheduled activity':'Your training plan'))}</p></section><div class="section"><div class="between">${btn('‹ Week','week','data-offset="-7"','button mini')} ${btn('Today','pickdate',`data-date="${C.dayKey()}"`,'button mini')} ${btn('Week ›','week','data-offset="7"','button mini')}</div><div class="weekday-strip space">${strip}</div>${field('Choose date',inp(date,'id="date"','date'))}</div>${!schedule()?card('<h3>Import your backup to get started</h3><p class="muted small">Use the private migration JSON supplied with LiftLog 2.0, or connect to your existing cloud database.</p>'+btn('Import backup','import','','button primary full')):''}${p.activities.map(a=>activityCard(a,date)).join('')||empty('Recovery / rest day. No mandatory activities.')}${sessions().filter(s=>s.date===date&&s.scheduled&&!s.extra&&!p.activities.some(a=>a.slot===s.slot)).map(s=>activityCard({kind:s.kind,slot:s.slot,title:s.title},date)).join('')}${card('<h3>Unscheduled activity</h3><div class="button-row space">'+C.TYPES.map(t=>btn(labels[t],'unscheduled',`data-kind="${t}"`,'button mini')).join('')+'</div>')}${recoveryCard()}${next?card(`<h3>Next unfinished activity</h3><p>${esc(niceDate(next.d))} · ${esc(next.a.title||labels[next.a.kind])}</p>`):''}`}
function recoveryCard(){let records=[...heads().values()].filter(e=>e.entity==='recovery'&&e.payload.date===date).map(e=>e.payload);return card(`<h3>Recovery check-in</h3><p class="muted small">Log soreness separately from a completed workout, including 48-hour follow-up. Scores 0–10.</p><div class="formgrid">${field('Stage',sel([['pre','Before exercise'],['24h','24 hours after'],['48h','48 hours after'],['other','Other']],'pre','id="recovery-stage"'))}${['quad','hamstring','calf'].map(m=>field(m,inp('',`id="recovery-${m}" min="0" max="10" step="1"`,'number'))).join('')}</div>${field('Related workout date / symptoms',inp('','id="recovery-notes"'))}${btn('Save check-in','recovery-save','','button full space')}${records.map(r=>`<div class="list-row"><div class="list-main"><strong>${esc(r.stage)} · ${esc(clock(r.recordedAt))}</strong><p class="small muted">Quad ${esc(r.quad||'—')} · Hamstring ${esc(r.hamstring||'—')} · Calf ${esc(r.calf||'—')} · ${esc(r.notes)}</p></div></div>`).join('')}`)}
function activityCard(a,d){let done=C.completedFor(db.events,d,a.slot);if(done)a={...a,title:done.title||a.title,notes:done.planSnapshot?.notes||'',exercises:done.planSnapshot?.exercises||done.exercises.map(e=>({...e,sets:e.sets.length}))};return card(`<div class="between"><h3>${esc(a.title||labels[a.kind])}</h3><span class="badge ${done?'green':a.optional?'opt':''}">${done?'Workout complete':a.optional?'Optional':labels[a.kind]}</span></div>${a.notes?`<p class="small muted">${esc(a.notes)}</p>`:''}${a.exercises?.map(e=>`<div class="list-row"><div class="list-main"><strong>${esc(e.name)}</strong> ${e.pt?'<span class="badge">PT</span>':''} ${e.optional?'<span class="badge opt">Optional</span>':''}<div class="small muted">${e.sets} set${e.sets===1?'':'s'} · ${esc(e.target||units[e.unit])}</div></div></div>`).join('')||''}${done?`<p class="success small space">Completed at ${esc(clock(done.completedAt))}</p>${a.kind==='lift'?btn('+ Add extra exercises','extra',`data-parent="${attr(done.key)}"`,'button primary full space'):''}${C.editable(done)?btn('Edit completed workout','edit',`data-key="${attr(done.key)}"`,'text-btn'):''}`:btn('Start '+labels[a.kind].toLowerCase(),'start',`data-slot="${attr(a.slot)}"`,'button primary full space')}`)}
function activeView(s){let conflicting=s.scheduled&&!edit&&C.completedFor(db.events,s.date,s.slot);let completed=s.exercises.reduce((sum,e)=>sum+e.sets.filter(x=>x.done).length,0),total=s.exercises.filter(e=>!e.skipped&&!e.optional).reduce((sum,e)=>sum+e.sets.length,0);return `<section class="hero"><div class="eyebrow">${edit?'Corrections · original completion retained':s.extra?'Extra activity':'Activity in progress'}</div><h1>${esc(s.title||labels[s.kind])}</h1><p class="lead">${esc(niceDate(s.date))} · Started ${esc(clock(s.startedAt))} · <strong id="elapsed">${elapsed(C.duration(s))}</strong></p>${s.kind==='lift'?`<div class="small space">${completed} checked sets · ${total} nonoptional, unskipped sets</div>`:''}</section>${conflicting?card(note('A different device already completed this planned activity. Your local draft is still intact. Save it as additional activity to avoid a duplicate.')+btn('Convert to additional activity','convert-draft','','button full space')):''}${s.kind==='lift'?`${!edit?timerView():''}${note(s.planSnapshot?.notes)}${s.exercises.map((e,i)=>exerciseCard(e,i,s)).join('')}${btn('+ Exercise','add-ex','','button full space')}`:card(cardioView(s))}${card(`<h3>Notes & recovery</h3>${field('Workout notes',ta(s.notes,'data-sfield="notes"'))}${s.kind==='lift'?`<details class="space"><summary>Soreness & discomfort (optional)</summary>${['pre','24h','48h'].map(stage=>`<h3 class="small space">${stage}</h3><div class="formgrid">${['quad','hamstring','calf'].map(m=>field(m,inp(s.soreness?.[stage]?.[m]??'',`data-sore="${stage}:${m}" min="0" max="10" step="1"`,'number'))).join('')}</div>`).join('')}${field('Discomfort / elbow / knee',ta(s.discomfort??'','data-sfield="discomfort"'))}</details>`:''}</div>`)}<div class="button-row sticky-finish">${btn(edit?'Save corrections':'Finish activity ✓','finish','','button primary')}${btn(edit?'Cancel':'Discard','discard','','button danger')}</div>`}
function timerView(){return `<div class="timer space"><div class="between"><div><span class="label">Manual rest timer</span><strong id="rest-clock">00:00</strong> <span class="small muted" id="rest-target">/ ${db.prefs.restSeconds}s</span></div><div class="flex">${btn('Start','timer-start','','button primary')}${btn('Pause','timer-pause','','button')}${btn('Reset','timer-reset','','button')}</div></div><div class="flex space">${sel([60,90,120,180].map(x=>[x,x+' sec']).concat([['custom','Custom']]),[60,90,120,180].includes(db.prefs.restSeconds)?db.prefs.restSeconds:'custom','id="timer-preset"')}${inp(db.prefs.restSeconds,'id="timer-seconds" min="1" max="3600" aria-label="Rest seconds"','number')}</div></div>`}
function exerciseCard(e,i,s){let last=lastExercise(e.name,s.id),rec=chosenRec(e.name),rv=rec?decision(rec.id)?.weight:null,pending=pendingRec(e.name),usable=['lb','lb_each'].includes(e.unit)&&!edit&&!e.skipped;let lastText=last?last.e.sets.filter(x=>x.done).map(x=>setText(last.e,x)).join(' · '):'No completed sets yet';let hdr=e.unit==='sec'?'Seconds':e.unit==='reach'?'Reaches':e.unit==='band'?'Steps':'Reps';return card(`<div class="between"><h3>${esc(e.name)} ${e.pt?'<span class="badge">PT</span>':''} ${e.optional?'<span class="badge opt">Optional</span>':''}</h3>${btn(e.skipped?'Unskip':'Skip','skip',`data-i="${i}"`,'text-btn')}</div><p class="small muted">${esc(e.target||'')} ${e.rir?' · '+esc(e.rir):''}</p>${e.instructions?note(e.instructions):''}<p class="small muted space">Last: ${esc(lastText)}</p>${rec?note(`Accepted suggestion: ${rv??rec.payload.weight} lb · ${rec.payload.target||''} · ${rec.explanation}`):e.suggestedWeight!==undefined&&e.suggestedWeight!==''?note('Planned weight: '+e.suggestedWeight+' lb'):''}${usable&&pending?note(`Pending AI weight: ${pending.payload.weight} lb · ${pending.explanation}`)+btn('Use AI recommended weight','use-rec',`data-i="${i}" data-id="${attr(pending.id)}"`,'button primary full space'):usable&&rec?btn('Use AI recommended weight','use-rec',`data-i="${i}" data-id="${attr(rec.id)}"`,'button full space'):''}${e.skipped?`<p class="space">Skipped: ${esc(e.skipReason||'No reason specified')}</p>`:`<div class="set-head"><span>Set</span><span>${['sec','reach','band'].includes(e.unit)?'Detail':units[e.unit]||'Weight'}</span><span>${hdr}</span><span>Done</span></div>${e.sets.map((x,j)=>setRow(e,x,i,j)).join('')}<div class="extra-actions">${btn('+ Set','add-set',`data-i="${i}"`,'text-btn')}${last?btn('Repeat last','repeat',`data-i="${i}"`,'text-btn'):''}${btn('− Last set','remove-set',`data-i="${i}"`,'text-btn danger-text')}${e.extra?btn('Remove exercise','remove-ex',`data-i="${i}"`,'text-btn danger-text'):''}</div>`}`)}
function setRow(e,x,i,j){let a=f=>`data-set="${i}:${j}:${f}"`,side=e.sideLabels?.[x.side==='L'?0:1]||x.side||'';let detail=e.unit==='sec'?'<span class="small muted">Timed</span>':e.unit==='reach'?sel([['','Direction'],['forward','Forward'],['back-left','Back left'],['back-right','Back right']],x.direction??'',a('direction')):e.unit==='band'?inp(x.band??'',a('band')+' placeholder="Band"'):inp(x.weight??'',a('weight')+' min="0" step="any" placeholder="'+(e.unit==='bodyweight'||e.unit==='step'?'optional':'lb')+'"','number','num');return `<div class="set-row ${x.done?'is-done':''}"><span class="set-number">${esc(side||j+1)}</span>${detail}${inp(x.reps??'',a('reps')+' min="0" step="any" inputmode="decimal" placeholder="'+(e.unit==='sec'?'sec':'#')+'"','number','num')}${btn(x.done?'✓':'○','done',`data-i="${i}" data-j="${j}"`,'set-done '+(x.done?'checked':''))}</div>${e.unit==='step'?field('Step height (inches)',inp(x.height??'',a('height')+' min="0" step="any"','number')):''}<details class="small"><summary>Set details / RIR</summary>${field('RIR (optional)',inp(x.rir??'',a('rir')+' min="0" max="20"','number'))}${field('Notes',inp(x.notes??'',a('notes')))}</details>`}
function cardioView(s){let swim=s.kind==='swim',tot=swim?C.swimTotals(s.segments):C.runTotals(s.segments);return `<h3>${swim?'Swimming details (optional)':'Movement segments'}</h3><p class="muted small">${swim?'One length = one end to the other. Distance entered directly overrides length × pool length. Leave all optional fields blank for duration-only swimming.':'Enter distance and speed for each jogging or walking interval. Elapsed workout time is separate from calculated moving time.'}</p>${swim?field('Recorded swim duration (minutes, optional)',inp(s.activitySeconds!==undefined&&s.activitySeconds!==''?s.activitySeconds/60:'','data-sfield="activityMinutes" min="0" step="any"','number')):''}<div id="cardio-totals" class="note space">${totalsText(s)}</div>${s.segments.map((x,i)=>{let a=f=>`data-seg="${i}:${f}"`;return `<div class="sep"></div><div class="between"><h3>Segment ${i+1}</h3>${btn('Remove','remove-seg',`data-i="${i}"`,'text-btn danger-text')}</div><div class="formgrid">${swim?field('Pool length',inp(x.poolLength,a('poolLength')+' min="1" step="any"','number'))+field('Unit',sel([['yd','Yards'],['m','Meters']],x.unit,a('unit')))+field('Lengths',inp(x.lengths,a('lengths')+' min="0" step="1"','number'))+field('Direct distance',inp(x.distance,a('distance')+' min="0" step="any"','number'))+field('Seconds (optional)',inp(x.seconds,a('seconds')+' min="0"','number'))+field('Stroke',sel([['','Unspecified'],['breaststroke','Breaststroke'],['backstroke','Backstroke'],['freestyle','Freestyle'],['butterfly','Butterfly'],['other','Other']],x.stroke,a('stroke'))):field('Distance (mi)',inp(x.distance,a('distance')+' min="0" step="any"','number'))+field('Speed (mph)',inp(x.speed,a('speed')+' min="0" step="any"','number'))+field('Movement',sel([['run','Run/jog'],['walk','Walk']],x.movement,a('movement')))}</div>`}).join('')}${btn('+ Segment','add-seg','','button full space')}`}
function totalsText(s){if(s.kind==='swim'){let t=C.swimTotals(s.segments);return `${s.activitySeconds!==undefined&&s.activitySeconds!==''?'Recorded '+elapsed(s.activitySeconds)+' · ':''}${t.meters===null?'Distance not entered':fmt(t.meters,1)+' m / '+fmt(t.meters/.9144,1)+' yd'} · ${t.lengths} recorded lengths · ${elapsed(t.seconds)} segment time`}let t=C.runTotals(s.segments);return `${fmt(t.distance,2)} mi · ${elapsed(t.seconds)} moving · ${fmt(t.speed,2)} mph · ${t.pace?Math.floor(Math.round(t.pace*60)/60)+':'+String(Math.round(t.pace*60)%60).padStart(2,'0'):'—'} min/mi`}
function historyView(){let all=sessions(),ss=all.filter(s=>historyFilter==='all'||s.kind===historyFilter);return title('History','Completed activities · 24-hour correction window')+`<div class="stat-grid space"><div class="stat"><div class="stat-num">${all.length}</div><div class="stat-label">Activities</div></div><div class="stat"><div class="stat-num">${all.flatMap(s=>s.exercises).flatMap(e=>e.sets).filter(x=>x.done).length}</div><div class="stat-label">Checked sets</div></div></div>${field('Filter',sel([['all','All activities'],...C.TYPES.map(t=>[t,labels[t]])],historyFilter,'id="history-filter"'))}${ss.map(s=>card(`<div class="between"><h3>${esc(s.title||labels[s.kind])}</h3><span class="badge green">${s.extra?'Extra':'Complete'}</span></div><p class="small muted">${esc(niceDate(s.date))} · ${esc(clock(s.startedAt))} → ${esc(clock(s.completedAt))} · ${elapsed(C.duration(s))}</p><details class="space"><summary>View recorded details</summary>${s.kind==='lift'?s.exercises.map(e=>`<div class="sep"></div><strong>${esc(e.name)}</strong>${e.skipped?`<p class="small muted">Skipped: ${esc(e.skipReason||'Unspecified')}</p>`:''}${e.sets.map(x=>`<div class="history-set"><span>${esc(setText(e,x))}</span><span>${x.done?'✓':'Not checked'}</span></div>`).join('')}`).join(''):note(totalsText(s))+`<pre class="pre">${esc(JSON.stringify(s.segments,null,2))}</pre>`}${s.notes?note(s.notes):''}${s.discomfort?note(s.discomfort):''}${s.soreness?`<pre class="pre">${esc(JSON.stringify(s.soreness,null,2))}</pre>`:''}</details>${C.editable(s)?btn('Edit completed workout','edit',`data-key="${attr(s.key)}"`,'text-btn'):'<p class="small muted space">Read-only</p>'}${s.kind==='lift'&&!s.extra?btn('+ Add extra exercises','extra',`data-parent="${attr(s.key)}"`,'button full space'):''}`)).join('')||empty('No completed activities.')}`}
function progressView(){let ss=sessions(),names=[...new Set(ss.flatMap(s=>s.exercises.filter(e=>e.sets.some(x=>x.done)).map(e=>e.name)))].sort();if(!names.includes(progressName))progressName=names[0]||'';let points=ss.slice().reverse().flatMap(s=>s.exercises.filter(e=>e.name===progressName&&e.sets.some(x=>x.done)).map(e=>({date:s.date,v:Math.max(...e.sets.filter(x=>x.done).map(x=>n(['lb','lb_each'].includes(e.unit)?x.weight:x.reps))),label:e.sets.filter(x=>x.done).map(x=>setText(e,x)).join(' · ')})));let graph=(pts)=>{if(!pts.length)return empty('No records yet');let p=pts.slice(-30),lo=Math.min(...p.map(x=>x.v)),hi=Math.max(...p.map(x=>x.v));if(lo===hi){lo=Math.max(0,lo-1);hi+=1}let xy=(x,i)=>[30+(p.length===1?140:i/(p.length-1)*280),150-(x.v-lo)/(hi-lo)*115];return `<svg viewBox="0 0 340 180" class="chart" role="img" aria-label="Progress chart"><line class="grid" x1="30" x2="310" y1="150" y2="150"/><line class="grid" x1="30" x2="310" y1="35" y2="35"/><text x="3" y="39">${esc(fmt(hi))}</text><text x="3" y="153">${esc(fmt(lo))}</text><polyline class="poly" points="${p.map((x,i)=>xy(x,i).join(',')).join(' ')}"/>${p.map((x,i)=>{let [a,b]=xy(x,i);return `<circle class="dot" cx="${a}" cy="${b}" r="4"/>`}).join('')}<text x="30" y="170">${esc(p[0].date.slice(5))}</text><text x="310" y="170" text-anchor="end">${esc(p.at(-1).date.slice(5))}</text></svg>`};return title('Progress','Actual checked sets, not estimated one-rep max.')+card(field('Exercise',sel(names.map(x=>[x,x]),progressName,'id="progress-name"'))+`<p class="small muted space">Best logged load / reps / seconds per session · ${points.length} sessions</p>`+graph(points)+points.slice().reverse().map(p=>`<div class="list-row"><div class="list-main"><strong>${esc(p.date)}</strong><div class="small muted">${esc(p.label)}</div></div><strong>${esc(p.v)}</strong></div>`).join(''))+card('<h3>Running distance (mi)</h3>'+graph(ss.filter(s=>s.kind==='run').reverse().map(s=>({date:s.date,v:C.runTotals(s.segments).distance}))))+card('<h3>Running average movement speed (mph)</h3>'+graph(ss.filter(s=>s.kind==='run').reverse().map(s=>({date:s.date,v:C.runTotals(s.segments).speed}))))+card('<h3>Swimming duration (minutes)</h3>'+graph(ss.filter(s=>s.kind==='swim').reverse().map(s=>({date:s.date,v:(s.activitySeconds!==undefined&&s.activitySeconds!==''?Number(s.activitySeconds):C.duration(s))/60}))))}
function initPlan(){planBase=head('schedule')?.id??'';let w=C.weekAt(schedule(),effective);planDraft=planMode==='recurring'?w: C.planFor(schedule(),effective);}
function scheduleView(){if(!planDraft)initPlan();let p=planMode==='recurring'?planDraft[scheduleDay]:planDraft;let rev=head('schedule');return title('Schedule','Edit future plans without changing recorded workouts.')+card(`<div class="formgrid">${field('Change type',sel([['recurring','Recurring weekly'],['temporary','One date / date range']],planMode,'id="plan-mode"'))}${field('Effective date',inp(effective,'id="effective"','date'))}${planMode==='temporary'?field('Through date',inp(until,'id="until"','date')):''}</div>${planMode==='recurring'?`<div class="weekday-strip space">${C.DAY.map((d,i)=>`<button class="day ${i===scheduleDay?'active':''}" data-act="sched-day" data-i="${i}">${d.slice(0,3)}</button>`).join('')}</div>`:''}${field('Day notes',ta(p.notes??'','data-plan="notes"'))}${p.activities.map((a,i)=>card(`<div class="between"><h3>${esc(labels[a.kind])}</h3>${btn('Remove','plan-remove-a',`data-i="${i}"`,'text-btn danger-text')}</div>${field('Title',inp(a.title??'',`data-pa="${i}:title"`))}${field('Notes / instructions',ta(a.notes??'',`data-pa="${i}:notes"`))}<label class="small">${check(a.optional,`data-pa="${i}:optional"`)} Optional activity</label>${a.exercises?.map((e,j)=>`<div class="sep"></div><div class="between"><strong>Exercise ${j+1}</strong><div>${btn('↑','plan-move',`data-i="${i}" data-j="${j}" data-offset="-1"`,'text-btn')}${btn('↓','plan-move',`data-i="${i}" data-j="${j}" data-offset="1"`,'text-btn')}${btn('×','plan-remove-e',`data-i="${i}" data-j="${j}"`,'text-btn danger-text')}</div></div>${field('Name',inp(e.name,`data-pe="${i}:${j}:name"`))}<div class="formgrid">${field('Measurement',sel(Object.entries(units),e.unit,`data-pe="${i}:${j}:unit"`))}${field('Sets',inp(e.sets,`data-pe="${i}:${j}:sets" min="1" max="20"`,'number'))}${field('Target reps / time',inp(e.target??'',`data-pe="${i}:${j}:target"`))}${field('Suggested weight (optional)',inp(e.suggestedWeight??'',`data-pe="${i}:${j}:suggestedWeight" min="0" step="any"`,'number'))}</div><div class="flex wrap small"><label>${check(e.optional,`data-pe="${i}:${j}:optional"`)} Optional</label><label>${check(e.pt,`data-pe="${i}:${j}:pt"`)} PT</label><label>${check(e.unilateral,`data-pe="${i}:${j}:unilateral"`)} Unilateral / directions</label></div>${field('RIR / intensity',inp(e.rir??'',`data-pe="${i}:${j}:rir"`))}${field('Instructions',ta(e.instructions??'',`data-pe="${i}:${j}:instructions"`))}${planMode==='recurring'?btn('Move to another day','plan-move-day',`data-i="${i}" data-j="${j}"`,'button mini') :''}`).join('')||''}${a.kind==='lift'?btn('+ Exercise','plan-add-e',`data-i="${i}"`,'button full space'):''}`)).join('')}<div class="button-row space">${C.TYPES.map(k=>btn('+ '+labels[k],'plan-add-a',`data-kind="${k}"`,'button mini')).join('')}</div>${planMode==='recurring'?`<div class="space"><label class="small">${check(supersedeFuture,'id="supersede-future"')} Replace later recurring versions (including already planned future schedules)</label></div><div class="space"><label class="small">${check(clearOverrides,'id="clear-overrides"')} Clear date overrides on and after effective date</label></div>`:''}${field('Reason / explanation',inp(planReason,'id="plan-reason"'))}${btn('Review & save','plan-save','','button primary full space')}${planMode==='temporary'?btn('Remove date overrides','plan-clear','','button full space'):''}${btn('Reload saved plan','plan-reload','','text-btn')}`)+card(`<h3>Schedule versions</h3><p class="small muted">Current revision: ${esc(rev?.id||'none')}</p>${schedule()?.versions.slice().reverse().map(v=>`<div class="list-row"><div class="list-main"><strong>${esc(v.effective)}</strong><p class="small muted">${esc(v.explanation||v.id)} · ${esc(v.source||'manual')} · ${esc(v.createdAt||'')}</p></div>${btn('Restore','restore-plan',`data-version="${attr(v.id)}"`,'button mini')}</div>`).join('')||'<p>No schedule.</p>'}<details class="space"><summary>All revision history / restore snapshot</summary>${db.events.filter(e=>e.entity==='schedule').slice().reverse().map(e=>`<div class="list-row"><div class="list-main small">${esc(e.at)} · ${esc(e.source)}<div class="muted">${esc(e.id)}</div></div>${btn('Restore','restore-snapshot',`data-event="${attr(e.id)}"`,'button mini')}</div>`).join('')}</details>`)}
function currentPlan(){return planMode==='recurring'?planDraft[scheduleDay]:planDraft}
function scheduleChange(change,explanation,source='manual',id){let current=schedule()??{versions:[{id:'initial',effective:'1900-01-01',weekly:C.blankWeek(),source:'manual',createdAt:C.now()}],overrides:{}};if(change.mode==='recurring'&&change.effective<C.dayKey())throw Error('Choose today or a future effective date');if(change.mode==='temporary'&&Object.keys(change.overrides).some(d=>d<C.dayKey()))throw Error('Past dates cannot be edited');let next=C.applyChange(current,change,{source,explanation,id:id||C.uid()});addEvent('schedule','schedule',next,source);planDraft=null;planReason='';supersedeFuture=false;clearOverrides=false;commit();render();toast('Schedule queued for saving')}
function proposalSummary(p){if(p.kind==='weight'){let l=lastExercise(p.payload.exercise);return `<p>${esc(p.payload.exercise)} · <strong>${esc(p.payload.weight)} lb</strong> · ${esc(p.payload.target||'')}</p><p class="small muted">Previous: ${esc(l?l.e.sets.filter(x=>x.done).map(x=>setText(l.e,x)).join(' · '):'No checked sets')}</p>`}let c=p.payload;try{let next=C.applyChange(schedule(),c,{source:'AI preview'}),dates=c.mode==='recurring'?Array.from({length:7},(_,i)=>C.addDays(c.effective,i)):Object.keys(c.overrides).sort();let summarize=p=>[p.notes,p.activities.map(a=>`${a.title||a.kind}${a.optional?' [optional]':''}${a.notes?' — '+a.notes:''}${a.exercises?' ('+a.exercises.map(e=>e.name+' ×'+e.sets+(e.target?' @ '+e.target:'')+(e.suggestedWeight!==undefined&&e.suggestedWeight!==''?' / '+e.suggestedWeight+' lb':'')+(e.rir?' / '+e.rir:'')+(e.optional?' [optional]':'')+(e.pt?' [PT]':'')).join(', ')+')':''}`).join('; ')||'Rest'].filter(Boolean).join(' · ');return `${head('schedule')?.id!==p.base?note('Stale base revision; request a refreshed proposal before applying.'):''}<p class="small">${esc(c.mode==='recurring'?'Recurring from '+c.effective:'Date-specific changes')}</p><details class="space"><summary>Compare current and proposed</summary>${dates.map(d=>`<div class="sep"></div><strong>${esc(d)}</strong><p class="small muted">Before: ${esc(summarize(plan(d)))}</p><p class="small">After: ${esc(summarize(C.planFor(next,d)))}</p>`).join('')}</details>`}catch(e){return note('Invalid proposal: '+e.message)}}
function aiView(){let prof=profileDraft??head('profile')?.payload??{};return title('AI & training profile','Optional coaching through your existing ChatGPT project.')+card(`<h3>ChatGPT project connection</h3><p class="small muted">Embedded inference is not enabled: remotely hosted subscription integration needs approval. Use the private Google Sheet from your regular ChatGPT project. Sync to retrieve proposals and recommendations.</p><div class="button-row space">${btn('Open ChatGPT','chatgpt')}${btn('Sync now','sync')}</div>${db.config.sheetId?`<p class="small muted space">Sheet: ${esc(db.config.sheetId)}</p>${btn('Open private Sheet','open-sheet','','text-btn')}`:''}`)+card(`<h3>Recommendations & proposals</h3>${db.inbox.length?db.inbox.map(p=>{let d=decision(p.id);return `<div class="sep"></div><div class="between"><strong>${p.kind==='weight'?'Working weight':'Schedule proposal'}</strong><span class="badge">${esc(d?.status||p.approval)}</span></div><p class="small muted">${esc(p.createdAt)}</p>${proposalSummary(p)}<p class="small space">${esc(p.explanation)}</p>${!d&&p.approval!=='REJECTED'?`<div class="button-row space">${btn(p.kind==='weight'?'Accept':'Apply','approve',`data-id="${attr(p.id)}"`,'button primary')}${p.kind==='weight'?btn('Modify','modify-rec',`data-id="${attr(p.id)}"`):''}${btn('Reject','reject',`data-id="${attr(p.id)}"`)}</div>`:''}`}).join(''):empty('No proposals yet. Ask your ChatGPT project to write an AI Inbox row.')}${syncErrors.map(x=>note(x)).join('')}`)+card(`<h3>Shared training profile</h3><p class="small muted">Only share information you approve. Saving this profile queues it for the private Sheet.</p>${['objectives','preferences','restrictions','soreness','future','equipment','limitations'].map(k=>field(k,ta(prof[k]??'',`data-profile="${k}"`))).join('')}${btn('Save profile','save-profile','','button primary full space')}`)+card(`<h3>Manual proposal import (fallback)</h3><p class="small muted">Paste a JSON object from ChatGPT if direct Sheets writing is unavailable. Fields: id, createdAt, kind, base, payload, explanation, approval.</p>${ta(proposalInput,'id="proposal-input"')}${btn('Import proposal','paste-proposal','','button full space')}`)}
function settingsView(){let conflicts=C.replay(db.events).conflicts;return title('Settings','Preferences, local backups and synchronization.')+card(`<h3>Appearance & rest alerts</h3>${field('Theme',sel([['teal','Charcoal / turquoise'],['blue','Navy / blue'],['purple','Charcoal / purple'],['lime','Dark gray / lime']],db.prefs.theme,'data-pref="theme"'))}${field('Rest seconds',inp(db.prefs.restSeconds,'data-pref="restSeconds" min="1" max="3600"','number'))}${['sound','vibration','wake'].map(k=>`<div class="space"><label>${check(db.prefs[k],`data-pref="${k}"`)} ${k==='wake'?'Keep screen awake during active workout':k==='sound'?'Play sound':'Vibrate'}</label></div>`).join('')}${field('Default pool length',inp(db.prefs.poolLength,'data-pref="poolLength" min="1" step="any"','number'))}${field('Pool unit',sel([['yd','Yards'],['m','Meters']],db.prefs.poolUnit,'data-pref="poolUnit"'))}<p class="small muted space">Alerts are best-effort while app is visible. Background or locked-screen alerts are not guaranteed.</p>`)+card(`<h3>Google synchronization</h3><p class="small muted">Private Google Sheets; one-time OAuth setup is required. Tokens stay in memory and expire. No public data endpoints.</p>${field('OAuth web client ID',inp(db.config.clientId,'data-config="clientId" placeholder="…apps.googleusercontent.com"'))}${field('Spreadsheet ID (or URL)',inp(db.config.sheetId,'data-config="sheetId" placeholder="Leave empty to create"'))}<div class="button-row space">${btn('Authorize Google','authorize','','button primary')}${btn('Disconnect','disconnect')}</div><div class="button-row space">${btn('Create private Sheet','create-sheet')}${btn('Sync now','sync')}</div><p class="small muted space">${esc(syncMessage||'Not synchronized yet.')}<br>Last verified sync: ${esc(db.lastSync||'Never')}<br>Pending events: ${db.events.filter(e=>!db.remoteIds.includes(e.id)).length}</p>${db.config.sheetId?btn('Open Sheet','open-sheet','','text-btn'):''}${syncErrors.map(x=>note(x)).join('')}`)+card(`<h3>Conflicts & recovery</h3>${conflicts.length?conflicts.map((c,i)=>`<div class="sep"></div><strong>${esc(c.event.key)} · ${esc(c.reason)}</strong><p class="small muted">Both versions retained in event archive. The first confirmed revision remains displayed.</p><details><summary>Inspect conflicting revision</summary><pre class="pre">${esc(JSON.stringify(c.event,null,2))}</pre></details>${c.event.entity==='schedule'?btn('Restore conflicting schedule','conflict-restore',`data-i="${i}"`,'button mini'):''}</div>`).join(''):'<p class="small muted">No conflicts detected.</p>'}`)+mediaBackupView()+extensionConflictView()+card(`<h3>Backups & storage</h3><div class="stack space">${btn('Export complete JSON','export-json','','button primary')}${btn('Import / restore JSON','import')}${btn('Export CSV','export-csv')}${btn('Request persistent device storage','persistent')}${btn('Check for app update','update')}</div><p class="small muted space">JSON preserves event history and active drafts. CSV is for analysis only. Export before clearing browser storage. Google credentials are not exported.</p>`)+card('<h3>LiftLog 2.0</h3><p class="small muted">Offline-first PWA · no ads · no subscription required. Install from browser menu. Direct Samsung Health import is deferred.</p>')}
function download(name,content,type){let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportJSON(){let b=C.clone(db);b.config={clientId:'',sheetId:''};b.remoteIds=[];if(b.extension){b.extension.remoteIds=[];delete b.extension.proposals;delete b.extension.delivered;delete b.extension.calendar;}b.lastSync=null;download('LiftLog-v2-backup-'+C.dayKey()+'.json',JSON.stringify(b,null,2),'application/json');toast('Backup exported')}
function exportCSV(){let rows=[['ID','Date','Activity','Start','Finish','Elapsed seconds','Recorded activity seconds','Exercise','Set','Side','Unit','Weight','Reps or seconds','Done','Skipped','Reason','Direction','Band','Step height in','RIR','Set notes','Segment JSON','Workout notes','Discomfort','Soreness JSON']];for(let s of sessions()){let b=[s.id,s.date,s.kind,s.startedAt,s.completedAt,C.duration(s),s.activitySeconds??''];if(s.kind==='lift')for(let e of s.exercises)for(let [i,x] of e.sets.entries())rows.push([...b,e.name,i+1,x.side,e.unit,x.weight,x.reps,x.done,e.skipped||false,e.skipReason||'',x.direction,x.band,x.height,x.rir,x.notes,'',s.notes,s.discomfort,JSON.stringify(s.soreness??{})]);else for(let x of s.segments.length?s.segments:[{}])rows.push([...b,...Array(14).fill(''),JSON.stringify(x),s.notes,s.discomfort,JSON.stringify(s.soreness??{})])}let csv=x=>'"'+String(x??'').replace(/^[=+\-@\t\r]/,m=>"'"+m).replaceAll('"','""')+'"';download('LiftLog-workouts-'+C.dayKey()+'.csv','\ufeff'+rows.map(r=>r.map(csv).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
async function importFile(file){if(!file)return;try{let b=JSON.parse(await file.text());if(b.version===1){let m=C.migrateV1(b,C.legacySchedule(b)),tmp=C.newDB();tmp.legacy=m.legacy;tmp.legacyPreferences=m.prefs;tmp.events.push(C.eventFor(tmp.events,'schedule','schedule',m.schedule,'migration','legacy-schedule-'+(b.exportedAt||'unknown'),b.exportedAt||C.now()));for(let s of m.sessions){if(s.status==='active')tmp.draft=s;else tmp.events.push(C.eventFor(tmp.events,'session',s.key,s,'migration','migration-v1-'+s.id,s.completedAt))}b=tmp}if(syncing||mediaBusy||saving)throw Error('Wait for current saves or synchronization to finish, then retry.');if(edit||planDraft)throw Error('Save or close the current editor before importing a backup.');const prepared=prepareImport(db,b);if(!confirm('Merge backup with local data? '+prepared.added+' workout revisions and '+prepared.extensionAdded+' other revisions will be added. '+prepared.conflicts+' conflicting revisions will remain available for review. No cloud settings will be imported.'))return;db=prepared.next;planDraft=null;let ok=await commit();view='workout';render();toast(ok?'Backup merged: '+prepared.added+' workout revisions, '+prepared.extensionAdded+' other revisions':'Backup merged in memory only; local save failed. Export a backup immediately.')}catch(e){alert('Import stopped: '+e.message)}finally{$('import-file').value=''}}
let syncTimer;function scheduleSync(){if(G.authorized()&&db.config.sheetId&&navigator.onLine){clearTimeout(syncTimer);syncTimer=setTimeout(()=>sync(false),1500)}}
async function sync(manual=false){if(syncing)return;if(!db.config.sheetId||!G.authorized()||!navigator.onLine){if(manual)toast('Connect Google and set a Sheet ID first. Internet required.');return}syncing=true;status();try{let id=db.config.sheetId;let first=await G.readSheet(id);if(id!==db.config.sheetId)throw Error('Sheet configuration changed');let m=C.mergeRemote(db.events,first.remote);db.events=m.events;db.remoteIds=m.remoteIds;await persist();let pending=db.events.filter(e=>!db.remoteIds.includes(e.id));await G.appendEvents(id,pending);let verify=await G.readSheet(id);if(id!==db.config.sheetId)throw Error('Sheet configuration changed');let confirmed=new Set(verify.remote.map(e=>e.id));if(!pending.every(e=>confirmed.has(e.id)))throw Error('Could not verify all uploaded events');m=C.mergeRemote(db.events,verify.remote);db.events=m.events;db.remoteIds=m.remoteIds;syncErrors=verify.errors;for(let p of [...verify.inbox,...[...heads().values()].filter(e=>e.entity==='proposal').map(e=>e.payload)]){let index=db.inbox.findIndex(x=>x.id===p.id);if(index<0)db.inbox.push(p);else if(!decision(p.id))db.inbox[index]=p}await syncExtensions(id);db.lastSync=C.now();syncMessage=`Verified ${confirmed.size} workout-log events and ${X.initExt(db).remoteIds.length} extension events.`;await persist();await autoApply();if(manual)toast(syncMessage);if(!active()&&!planDraft&&!['planner','subscriptions','food','measurements','measurement-settings'].includes(view)&&!document.activeElement?.matches('input,textarea,select'))render();else status()}catch(e){syncMessage='Sync not verified: '+e.message;await persist();if(manual)alert(syncMessage)}finally{syncing=false;status();if(view==='settings'&&!document.activeElement?.matches('input,textarea,select'))render()}}
async function autoApply(){if(active()||planDraft)return;for(let p of db.inbox.filter(x=>x.approval==='APPROVED'&&!decision(x.id))){try{applyProposal(p,true)}catch(e){syncErrors.push(p.id+': '+e.message)}}}
function applyProposal(p,auto=false,weight){if(decision(p.id))throw Error('Proposal already decided');if(p.approval==='REJECTED')throw Error('Rejected proposal');if(p.kind==='schedule'){if(active()||planDraft)throw Error('Finish active workout or exit schedule editing first');if(head('schedule')?.id!==p.base)throw Error('Schedule has changed since proposal; request a new proposal');let change=p.payload;if(change.mode==='recurring'&&change.effective<C.dayKey()||change.mode==='temporary'&&Object.keys(change.overrides??{}).some(d=>d<C.dayKey()))throw Error('Proposal contains past dates');let next=C.applyChange(schedule(),change,{source:'AI',explanation:p.explanation,id:p.id});let e=addEvent('schedule','schedule',next,'AI');addEvent('decision','decision:'+p.id,{status:'applied',eventId:e.id,approvedAt:C.now()},'AI')}else{let w=weight??p.payload.weight;if(w===''||!Number.isFinite(Number(w))||Number(w)<0)throw Error('Invalid recommended weight');addEvent('decision','decision:'+p.id,{status:'accepted',weight:Number(w),approvedAt:C.now()},'AI')}commit();if(!auto){render();toast('Approved proposal saved locally')}}
function tick(){if(!db)return;let s=active();if($('elapsed')&&s)$('elapsed').textContent=elapsed(C.duration(s));let t=db.timer;let ms=t?(t.running?Date.now()-t.start+t.accumulated:t.accumulated):0;let target=t?.target??db.prefs.restSeconds;if(t?.running&&ms>=target*1000){db.timer=null;persist();if(document.visibilityState==='visible')alertRest();ms=0;toast('Rest interval complete')}if($('rest-clock'))$('rest-clock').textContent=(ms>=3600000?elapsed(ms/1000):elapsed(ms/1000).slice(3));if($('rest-target'))$('rest-target').textContent='/ '+target+'s'}
function alertRest(){if(db.prefs.vibration)navigator.vibrate?.([200,100,200]);if(db.prefs.sound&&audio?.state==='running'){let o=audio.createOscillator(),g=audio.createGain();o.frequency.value=660;g.gain.value=.12;o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.25)}}
async function keepAwake(){if(db?.draft&&db.prefs.wake&&document.visibilityState==='visible'&&!wakeLock){try{wakeLock=await navigator.wakeLock?.request('screen');wakeLock?.addEventListener('release',()=>wakeLock=null)}catch{}}else if((!db?.draft||!db.prefs.wake)&&wakeLock){await wakeLock.release();wakeLock=null}}
function makeSegment(kind){return kind==='swim'?{id:C.uid(),poolLength:db.prefs.poolLength,unit:db.prefs.poolUnit,lengths:'',distance:'',seconds:'',stroke:''}:{id:C.uid(),distance:'',speed:'',movement:kind==='walk'?'walk':'run'}}
function addExercise(s){U.exercisePicker('workout',def=>{if(active()!==s)throw Error('Workout changed');s.exercises.push(C.freshExercise({...def,extra:true}));handleDraft()})}
function freshDraft(a,opts){if(db.draft||edit)throw Error('Finish current activity first');if(opts?.scheduled!==false&&C.completedFor(db.events,date,a.slot))throw Error('Scheduled activity already completed');db.draft=C.startSession(date,a,opts);view='workout';if(a.kind==='run'||a.kind==='walk')db.draft.segments.push(makeSegment(a.kind));commit();render();keepAwake();scrollTo(0,0)}
function handleDraft(){if(!edit)persist()}
async function finish(){let s=active();if(!s||saving>100)return;if(edit&&head(s.key)?.id!==editBase)throw Error('A synchronized correction changed this workout. Cancel and reopen the latest revision.');if(edit&&!C.editable(head(s.key)?.payload??s))throw Error('24-hour correction window expired');if(s.kind==='lift'&&!s.exercises.some(e=>e.sets.some(x=>x.done))&&!confirm('No checked sets. Finish anyway?'))return;if(s.kind==='lift'&&s.exercises.some(e=>!e.skipped&&!e.optional&&e.sets.some(x=>!x.done))&&!confirm('Some required sets are unchecked. Finish with incomplete sets?'))return;if(s.kind==='run'||s.kind==='walk'){if(s.segments.some(x=>x.distance===''||x.speed===''||Number(x.speed)<=0))throw Error('Complete or remove each movement segment')}if(s.kind==='swim'&&s.segments.some(x=>x.lengths!==''&&(!Number(x.poolLength)||Number(x.poolLength)<0)))throw Error('Enter positive pool length');let copy=C.clone(s);copy.status='completed';if(!edit){copy.completedAt=C.now();if(copy.scheduled&&C.completedFor(db.events,copy.date,copy.slot))throw Error('A synchronized copy of this activity already exists. Export backup before resolving.')}C.validateSession(copy);addEvent('session',copy.key,copy,edit?'correction':'manual');edit=null;db.draft=null;db.timer=null;let ok=await commit();keepAwake();view='workout';date=copy.date;render();scrollTo(0,0);if(ok){toast('Activity saved');autoApply()}else toast('Not saved to storage — export backup immediately')}
function changePlanDay(i,j,offset){let es=currentPlan().activities[i].exercises,k=j+offset;if(k>=0&&k<es.length)[es[j],es[k]]=[es[k],es[j]]}
function handleAction(b){let action=b.dataset.act,i=Number(b.dataset.i),j=Number(b.dataset.j),s=active(),e=s?.exercises[i],x=e?.sets[j];switch(action){
case 'nav':if(b.dataset.v===view)return;if(b.dataset.v==='schedule')planDraft=null;else if(view==='schedule'){if(planDraft&&!confirm('Leave schedule editor? Unsaved changes will be discarded.'))return;planDraft=null}navigate(b.dataset.v);return;
case 'recovery-save':{let p={date,stage:$('recovery-stage').value,recordedAt:C.now(),quad:$('recovery-quad').value,hamstring:$('recovery-hamstring').value,calf:$('recovery-calf').value,notes:$('recovery-notes').value};if([p.quad,p.hamstring,p.calf].some(x=>x!==''&&(!Number.isInteger(Number(x))||Number(x)<0||Number(x)>10)))throw Error('Soreness scores must be integers 0–10');if([p.quad,p.hamstring,p.calf].every(x=>x==='')&&!p.notes.trim())throw Error('Enter a soreness score or notes');addEvent('recovery','recovery:'+C.uid(),p);commit();toast('Recovery check-in saved');break}
case 'pickdate':date=b.dataset.date;break;case 'week':date=C.addDays(date,Number(b.dataset.offset));break;
case 'start':{let a=plan(date).activities.find(x=>x.slot===b.dataset.slot);if(!a)throw Error('Activity not found');freshDraft(a);return}
case 'unscheduled':{let kind=b.dataset.kind,a={kind,slot:kind,title:'Unscheduled '+labels[kind],exercises:[]};if(kind==='lift'){U.exercisePicker('unscheduled',def=>{a.exercises=[def];freshDraft(a,{scheduled:false})});return}freshDraft(a,{scheduled:false});return}
case 'extra':{let parent=head(b.dataset.parent)?.payload;if(!parent)throw Error('Parent not found');U.exercisePicker('extra',def=>{date=parent.date;freshDraft({kind:'lift',slot:'extra',title:'Extra exercises',exercises:[{...def,extra:true}]},{extra:true,scheduled:false,parentId:parent.id})});return}
case 'edit':{if(db.draft||edit)throw Error('Finish current activity first');let p=head(b.dataset.key)?.payload;if(!p||!C.editable(p))throw Error('Correction window expired');edit=C.clone(p);editBase=head(p.key).id;view='workout';scrollTo(0,0);break}
case 'convert-draft':{if(!db.draft||!db.draft.scheduled)throw Error('No scheduled draft');let previous=C.completedFor(db.events,db.draft.date,db.draft.slot);if(!previous)throw Error('No duplicate detected');if(!confirm('Keep your current draft as additional activity, linked to the completed session?'))return;db.draft.key='session:'+db.draft.id;db.draft.extra=true;db.draft.scheduled=false;db.draft.parentId=previous.id;db.draft.title='Additional '+labels[db.draft.kind];handleDraft();break}
case 'done':if(!x)return;if(!x.done){if(!Number.isFinite(Number(x.reps))||Number(x.reps)<=0)throw Error('Enter positive reps / seconds first');if(['lb','lb_each'].includes(e.unit)&&(x.weight===''||!Number.isFinite(Number(x.weight))||Number(x.weight)<0))throw Error('Enter weight (0 allowed)');if(e.unit==='reach'&&!x.direction)throw Error('Select reach direction');if(e.unit==='band'&&!x.band)throw Error('Enter band resistance');if(e.unit==='step'&&(!Number(x.height)||Number(x.height)<=0))throw Error('Enter step height')}x.done=!x.done;handleDraft();break;
case 'skip':if(e.skipped){e.skipped=false;delete e.skipReason}else{if(e.sets.some(x=>x.done)&&!confirm('This exercise has checked sets. Keep them and mark remainder skipped?'))return;let r=prompt('Reason: injury, pain, recovery, equipment unavailable, other (blank = unspecified)','');if(r===null)return;e.skipped=true;e.skipReason=r}handleDraft();break;
case 'add-set':{let newSet=()=>({id:C.uid(),weight:'',reps:'',done:false});if(e.unit==='reach'){for(let side of e.unilateral?['L','R']:[''])for(let direction of ['forward','back-left','back-right'])e.sets.push({...newSet(),side,direction})}else if(e.unilateral)e.sets.push({...newSet(),side:'L'},{...newSet(),side:'R'});else e.sets.push(newSet());handleDraft();break}
case 'remove-set':{let k=(e.unilateral?2:1)*(e.unit==='reach'?3:1);if(e.sets.length<=k)throw Error('At least one set required');if(e.sets.slice(-k).some(x=>x.done)&&!confirm('Remove checked set(s)?'))return;e.sets.splice(-k);handleDraft();break}
case 'repeat':{let last=lastExercise(e.name,s.id);if(last){let old=last.e.sets.filter(x=>x.done);e.sets.forEach((x,k)=>{let z=old[k];if(z){for(let f of ['weight','reps','height','band','direction'])if(z[f]!==undefined)x[f]=z[f];x.done=false}});handleDraft()}break}
case 'add-ex':addExercise(s);return;case 'use-rec':{let p=db.inbox.find(q=>q.id===b.dataset.id);if(!p||isTechnicalTest(p)||p.kind!=='weight'||!e||edit||e.skipped||!['lb','lb_each'].includes(e.unit)||p.payload.exercise.toLowerCase()!==e.name.toLowerCase())throw Error('Recommendation is no longer applicable');let d=decision(p.id);if(p.approval==='REJECTED'||(d&&d.status!=='accepted'))throw Error('Recommendation is not available');let w=Number(d?.weight??p.payload.weight);if(!Number.isFinite(w)||w<0)throw Error('Invalid recommended weight');if(!e.sets.some(z=>!z.done))throw Error('All sets are completed');if(e.sets.some(z=>!z.done&&z.weight!==''&&Number(z.weight)!==w)&&!confirm('Replace weights on unchecked sets only?'))return;if(!d)addEvent('decision','decision:'+p.id,{status:'accepted',weight:w,approvedAt:C.now()},'AI');for(const z of e.sets)if(!z.done)z.weight=String(w);commit();break}case 'remove-ex':if(confirm('Remove extra exercise?')){s.exercises.splice(i,1);handleDraft()}break;
case 'add-seg':s.segments.push(makeSegment(s.kind));handleDraft();break;case 'remove-seg':s.segments.splice(i,1);handleDraft();break;
case 'finish':finish().catch(e=>alert(e.message));return;case 'discard':if(confirm(edit?'Discard corrections?':'Discard unfinished activity?')){if(edit)edit=null;else{db.draft=null;db.timer=null;commit();keepAwake()}break}return;
case 'timer-start':if(db.timer?.running)return;try{audio??=new AudioContext();audio.resume()}catch{}db.timer={running:true,start:Date.now(),accumulated:db.timer?.accumulated||0,target:db.timer?.target||db.prefs.restSeconds};persist();keepAwake();break;
case 'timer-pause':if(db.timer?.running){db.timer.accumulated+=Date.now()-db.timer.start;db.timer.running=false;persist()}break;case 'timer-reset':db.timer=null;persist();break;
case 'sched-day':scheduleDay=i;break;case 'plan-reload':if(confirm('Discard unsaved changes?'))planDraft=null;break;
case 'plan-add-a':{let p=currentPlan(),kind=b.dataset.kind;let slot=kind;if(p.activities.some(a=>a.slot===slot))slot=kind+'-'+C.uid().slice(0,8);p.activities.push({kind,slot,title:labels[kind],notes:'',...(kind==='lift'?{exercises:[{name:'New exercise',unit:'lb',sets:2,target:'8–15'}]}:{})});break}
case 'plan-remove-a':currentPlan().activities.splice(i,1);break;case 'plan-add-e':{let a=currentPlan().activities[i];U.exercisePicker('schedule',def=>a.exercises.push(def));return}case 'plan-remove-e':currentPlan().activities[i].exercises.splice(j,1);break;case 'plan-move':changePlanDay(i,j,Number(b.dataset.offset));break;
case 'plan-move-day':{let day=Number(prompt('Destination day: 0 Sunday, 1 Monday, … 6 Saturday'));if(!Number.isInteger(day)||day<0||day>6)throw Error('Invalid day');if(day===scheduleDay)return;let ex=currentPlan().activities[i].exercises.splice(j,1)[0],target=planDraft[day].activities.find(a=>a.kind==='lift');if(!target){target={kind:'lift',slot:'lift',title:'Lifting',exercises:[]};planDraft[day].activities.push(target)}target.exercises.push(ex);if(!currentPlan().activities[i].exercises.length)currentPlan().activities.splice(i,1);break}
case 'plan-save':case 'plan-clear':{if((head('schedule')?.id??'')!==planBase)throw Error('Schedule changed on another device. Reload the saved plan and review your edits.');let change;if(planMode==='recurring')change={mode:'recurring',effective,weekly:planDraft,supersedeFuture,clearOverrides};else{if(!C.isDate(effective)||!C.isDate(until)||until<effective)throw Error('Invalid date range');let overrides={};for(let d=effective;d<=until;d=C.addDays(d,1)){if(Object.keys(overrides).length>=366)throw Error('Maximum range 366 days');overrides[d]=action==='plan-clear'?null:planDraft}change={mode:'temporary',overrides}}let why=$('plan-reason').value;if(confirm('Save these future schedule changes? Completed sessions stay unchanged.')){scheduleChange(change,why);return}return}
case 'restore-plan':{let v=schedule().versions.find(v=>v.id===b.dataset.version),d=prompt('Restore weekly plan effective date',C.dayKey());if(d&&confirm('Restore this weekly plan from '+d+'? Existing date overrides remain.'))scheduleChange({mode:'recurring',effective:d,weekly:v.weekly},'Restore '+v.id);return}
case 'restore-snapshot':case 'conflict-restore':{let v=action==='restore-snapshot'?db.events.find(e=>e.id===b.dataset.event):C.replay(db.events).conflicts[i].event;let d=prompt('Restore weekly plan effective date',C.dayKey());if(d&&confirm('Restore this revision’s weekly plan from '+d+'? Existing date overrides remain.'))scheduleChange({mode:'recurring',effective:d,weekly:C.weekAt(v.payload,d)},'Restore revision '+v.id);return}
case 'save-profile':{let p={};document.querySelectorAll('[data-profile]').forEach(x=>p[x.dataset.profile]=x.value);if(confirm('Save and share this training profile when cloud sync is enabled?')){addEvent('profile','profile',p);profileDraft=null;commit();toast('Profile queued for saving')}break}
case 'paste-proposal':{let p=JSON.parse($('proposal-input').value);p=C.inboxItem([p.id,p.createdAt,p.kind,p.base,JSON.stringify(p.payload),p.explanation,p.approval||'PENDING']);if(db.inbox.some(x=>x.id===p.id))throw Error('Proposal ID already exists');p.approval='PENDING';db.inbox.push(p);addEvent('proposal','proposal:'+p.id,p);proposalInput='';commit();break}
case 'approve':case 'modify-rec':{let p=db.inbox.find(x=>x.id===b.dataset.id),w;if(action==='modify-rec'){w=prompt('Accepted weight in lb',p.payload.weight);if(w===null)return}if(confirm('Apply this recommendation or schedule change?'))applyProposal(p,false,w);return}
case 'reject':{let p=db.inbox.find(x=>x.id===b.dataset.id);if(!decision(p.id)){addEvent('decision','decision:'+p.id,{status:'rejected',approvedAt:C.now()});commit()}break}
case 'chatgpt':window.open('https://chatgpt.com/','_blank','noopener');return;case 'open-sheet':window.open('https://docs.google.com/spreadsheets/d/'+encodeURIComponent(db.config.sheetId)+'/edit','_blank','noopener');return;
case 'authorize':G.authorize(db.config.clientId).then(()=>{syncMessage='Google authorized for this session';render();scheduleSync()}).catch(e=>alert(e.message));return;
case 'disconnect':G.disconnect();mediaBackups=[];mediaMessage='';syncMessage='Disconnected locally; your private Sheet is unchanged.';break;
case 'create-sheet':if(!G.authorized())throw Error('Authorize Google first');if(db.config.sheetId&&!confirm('Create a new database instead of existing one?'))return;G.createSheet().then(id=>{db.config.sheetId=id;db.remoteIds=[];X.initExt(db).remoteIds=[];X.initExt(db).proposals=[];db.lastSync=null;commit();render();toast('Private Sheet created')}).catch(e=>alert(e.message));return;
case 'media-list':case 'media-create':case 'media-restore':mediaAction(action,b.dataset.id).catch(e=>alert(e.message));return;case 'sync':sync(true);return;case 'export-json':exportJSON();return;case 'export-csv':exportCSV();return;case 'import':$('import-file').click();return;
case 'persistent':navigator.storage?.persist?.().then(ok=>alert(ok?'Persistent storage granted':'Browser did not grant persistent storage; continue backups.'));return;
case 'update':navigator.serviceWorker?.getRegistration().then(async r=>{if(!r){toast('No service worker registered');return}await r.update();if(r.waiting){if(confirm('Reload to activate the app update? Save any open forms first. Your saved data will be retained.')){if(syncing||mediaBusy){toast('Finish current synchronization before updating');return}if(!await persist()){alert('Update stopped: local data could not be saved. Export a backup first.');return}navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});r.waiting?.postMessage('SKIP_WAITING')}}else toast('Update check complete')}).catch(e=>alert(e.message));return;
}render()}
function inputEvent(ev){let el=ev.target,ds=el.dataset,s=active(),value=el.type==='checkbox'?el.checked:el.value;if(ds.set&&s){let [i,j,f]=ds.set.split(':'),x=s.exercises[i].sets[j];x[f]=value;if(x.done&&['weight','reps','height','band','direction'].includes(f)){x.done=false;let b=el.closest('.set-row')?.querySelector('[data-act=done]');if(b){b.textContent='○';b.classList.remove('checked')}}handleDraft();return}if(ds.seg&&s){let [i,f]=ds.seg.split(':');s.segments[i][f]=value;handleDraft();$('cardio-totals').textContent=totalsText(s);return}if(ds.sfield&&s){if(ds.sfield==='activityMinutes'){s.activitySeconds=value===''?'':Number(value)*60;$('cardio-totals').textContent=totalsText(s)}else s[ds.sfield]=value;handleDraft();return}if(ds.sore&&s){let [stage,m]=ds.sore.split(':');s.soreness??={};s.soreness[stage]??={};s.soreness[stage][m]=value;handleDraft();return}if(ds.plan&&planDraft){currentPlan()[ds.plan]=value;return}if(ds.pa&&planDraft){let [i,f]=ds.pa.split(':');currentPlan().activities[i][f]=value;return}if(ds.pe&&planDraft){let [i,j,f]=ds.pe.split(':');currentPlan().activities[i].exercises[j][f]=f==='sets'?Number(value):value;return}if(ds.profile){profileDraft??=C.clone(head('profile')?.payload??{});profileDraft[ds.profile]=value;return}if(el.id==='proposal-input'){proposalInput=value;return}if(el.id==='plan-reason'){planReason=value;return}if(el.id==='supersede-future'){supersedeFuture=el.checked;return}if(el.id==='clear-overrides'){clearOverrides=el.checked;return}}
function changeEvent(ev){let el=ev.target,ds=el.dataset,v=el.type==='checkbox'?el.checked:el.value;inputEvent(ev);if(el.id==='date'){if(C.isDate(v)){date=v;render()}return}if(el.id==='history-filter'){historyFilter=v;render();return}if(el.id==='progress-name'){progressName=v;render();return}if(el.id==='plan-mode'){if(planMode!==v&&confirm('Switch editor type? Unsaved changes will be discarded.')){planMode=v;planDraft=null;until=effective}render();return}if(el.id==='effective'){if(C.isDate(v)&&confirm('Load schedule for this date? Unsaved changes will be discarded.')){effective=v;if(until<effective)until=effective;planDraft=null}render();return}if(el.id==='until'){until=v;return}if(el.id==='timer-preset'){if(v!=='custom'){db.prefs.restSeconds=Number(v);persist();render()}else $('timer-seconds').focus();return}if(el.id==='timer-seconds'){let t=Number(v);if(!Number.isInteger(t)||t<1||t>3600){alert('Enter 1–3600 seconds');render();return}db.prefs.restSeconds=t;persist();render();return}if(ds.pref){let k=ds.pref;if(['restSeconds','poolLength'].includes(k)){v=Number(v);if(!Number.isFinite(v)||v<=0||(k==='restSeconds'&&(!Number.isInteger(v)||v>3600))){alert('Invalid value');render();return}}db.prefs[k]=v;persist();render();keepAwake();return}if(ds.config){let k=ds.config;if(k==='sheetId'){if(syncing){alert('Wait for current sync to finish');render();return}v=v.trim();let match=v.match(/\/spreadsheets\/d\/([a-zA-Z0-9_-]+)/);if(match)v=match[1];if(v&&!/^[a-zA-Z0-9_-]+$/.test(v)){alert('Invalid spreadsheet ID');render();return}if(v!==db.config.sheetId){if(db.config.sheetId&&!confirm('Switch cloud database? Local events remain and will be merged into the new sheet.')){render();return}db.remoteIds=[];X.initExt(db).remoteIds=[];X.initExt(db).proposals=[];db.lastSync=null}}else{v=v.trim();if(v!==db.config.clientId)G.disconnect();if(v&&navigator.onLine)G.prepare().catch(()=>{})}db.config[k]=v;mediaBackups=[];mediaMessage='';persist();status();return}}
async function boot(){try{db=await S.load()||C.newDB();C.validateDB(db);db.inbox??=[];db.remoteIds??=[];db.config??={clientId:'',sheetId:''};X.initExt(db);if(db.draft)view='workout';U.connect({db:()=>db,persist:commit,render,navigate,quickAction});PUI.connect({db:()=>db,persist:commit,render,navigate});U.install();PUI.install();render();if(!await persist())return;document.addEventListener('click',ev=>{let b=ev.target.closest('[data-act]');if(!b)return;try{handleAction(b)}catch(e){alert(e.message)}});document.addEventListener('input',inputEvent);document.addEventListener('change',changeEvent);$('import-file').addEventListener('change',e=>importFile(e.target.files[0]));setInterval(tick,300);setInterval(()=>{if(document.visibilityState==='visible')PUI.syncCalendar()},300000);setInterval(()=>{if(document.visibilityState==='visible')sync(false)},60000);window.addEventListener('online',()=>sync(false));document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){tick();keepAwake();sync(false)}});if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(e=>toast('Offline installation unavailable: '+e.message))}if(db.draft)keepAwake();else PUI.openLink();setInterval(()=>PUI.notifyDue(),60000);PUI.notifyDue();}catch(e){$('view').innerHTML=title('Could not open LiftLog',e.message);$('status').textContent='Database unavailable';$('error').textContent='Do not clear site data. Try another tab or restore from a backup.'}}
if(navigator.locks){navigator.locks.request('liftlog-single-writer',{ifAvailable:true},async lock=>{if(!lock){$('view').innerHTML=title('LiftLog is already open','Close the other tab or installed app window, then reload.');return}await boot();await new Promise(()=>{})})}else boot();

async function syncExtensions(id){let x=X.initExt(db);await G.ensureExtensionTabs(id);let first=await G.readExtension(id);if(id!==db.config.sheetId)throw Error('Sheet configuration changed');let conflicts=X.mergeRemoteExt(db,first.remote);x.proposals=first.proposals;syncErrors.push(...first.errors,...conflicts.map(c=>'V2.1 revision conflict: '+c.event.key));for(let p of first.proposals){if(p.kind==='food'&&p.approval==='APPROVED'&&!X.getExt(db,'decision:'+p.id)){try{X.confirmedFood(db,p);X.saveExt(db,'decision:'+p.id,{status:'accepted',at:C.now()})}catch(err){syncErrors.push('Food proposal '+p.id+': '+err.message)}}}if(!await persist())throw Error('Extension save failed before upload');let pending=x.events.filter(e=>!x.remoteIds.includes(e.id));await G.appendExtension(id,pending);let verify=await G.readExtension(id);if(id!==db.config.sheetId)throw Error('Sheet configuration changed');let confirmed=new Set(verify.remote.map(e=>e.id));if(!pending.every(e=>confirmed.has(e.id)))throw Error('Could not verify V2.1 upload');X.mergeRemoteExt(db,verify.remote);x.proposals=verify.proposals;}

function extensionConflictView(){let cs=X.replayExt(X.initExt(db).events).conflicts;return card('<h3>V2.1 revision conflicts</h3>'+ (cs.length?cs.map(c=>`<details class="space"><summary>${esc(c.event?.key||'Unknown record')} · ${esc(c.reason)}</summary><p class="small muted">Both revisions retained. No automatic overwrite; export a backup before attempting recovery.</p><pre class="pre">${esc(JSON.stringify(c.event,null,2))}</pre></details>`).join(''):'<p class="small muted">No extension conflicts detected.</p>'))}
function mediaBackupView(){return card('<h3>Private photo backups (optional)</h3><p class="small muted">Photos are not automatically uploaded. Create a separate private Drive snapshot, then use Restore on another device with the same authorized Google account. This is not end-to-end encrypted. Do not upload sensitive images. The associated measurement, food and note metadata syncs separately.</p>'+`<p>${Object.keys(X.initExt(db).media).length} local photo files · ${G.authorized()?'Google connected':'Reconnect Google first'}</p>`+(mediaMessage?note(mediaMessage):'')+btn('Create private photo backup','media-create')+btn('Find my photo backups','media-list')+mediaBackups.map(f=>`<div class="list-row"><div class="list-main"><strong>${esc(f.name)}</strong><p class="small muted">${esc(f.createdTime||'')}</p></div>${btn('Restore','media-restore',`data-id="${attr(f.id)}"`)}</div>`).join(''))}
async function mediaAction(action,id){if(mediaBusy)return;if(!G.authorized())throw Error('Authorize Google first');mediaBusy=true;try{if(action==='media-create'){if(!confirm('Upload all local photos into a new private Drive backup using the currently authorized Google account? This includes progress, food and Planner photos and is not end-to-end encrypted.'))return;await M.createBackup(G.driveRequest,M.snapshot(db));mediaMessage='Private photo snapshot uploaded and verified.';mediaBackups=await M.listBackups(G.driveRequest)}else if(action==='media-list'){mediaBackups=await M.listBackups(G.driveRequest);mediaMessage=mediaBackups.length?`${mediaBackups.length} backup(s) found. Privacy is checked again before restore.`:'No backups found.'}else{if(!confirm('Restore missing local photo files? Existing photos and records will not be replaced.'))return;let snap=await M.restoreBackup(G.driveRequest,id),count=M.mergeSnapshot(db,snap);if(!await persist())throw Error('Local save failed. Keep the Drive backup.');mediaMessage=`${count} missing photo(s) restored.`}}finally{mediaBusy=false;render()}}
